package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen1Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValue_FirstTimeLong() {
        long val = 100L;
        frequency.addValue(val);
        assertEquals(1L, frequency.getCount(val));
        assertEquals(1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValue_FirstTimeInteger() {
        // The method converts Integer to Long internally
        Integer val = 42;
        frequency.addValue(val);
        // Since it converts to Long, we check using Long
        assertEquals(1L, frequency.getCount(42L));
    }

    @Test
    public void testAddValue_IncrementExistingLong() {
        long val = 100L;
        frequency.addValue(val);
        frequency.addValue(val);
        assertEquals(2L, frequency.getCount(val));
        assertEquals(2L, frequency.getSumFreq());
    }

    @Test
    public void testAddValue_IncrementExistingInteger() {
        Integer val = 42;
        frequency.addValue(val);
        frequency.addValue(val);
        // Check via Long because the internal map stores Long
        assertEquals(2L, frequency.getCount(42L));
    }

    @Test
    public void testAddValue_DifferentTypesMixingLongAndDouble() {
        // Adding Longs and Doubles (which are Comparable to each other in some contexts, 
        // but here we check if they can coexist in the TreeMap)
        frequency.addValue(10L);
        frequency.addValue(20.5);

        assertEquals(1L, frequency.getCount(10L));
        assertEquals(1L, frequency.getCount(20.5));
        assertEquals(2L, frequency.getSumFreq());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAddValue_IncompatibleTypesThrowsException() {
        // Add a Long first
        frequency.addValue(10L);
        // Try to add a String. String is not comparable to Long, 
        // causing TreeMap to throw ClassCastException, which is caught and rethrown as IllegalArgumentException
        frequency.addValue("Not a number");
    }

    @Test
    public void testAddValue_NullValue() {
        // Depending on TreeMap implementation, null might throw NPE or be handled.
        // In standard TreeMap, adding null after non-null values throws NPE.
        // The requirement asks for branch coverage.
        frequency.addValue(10L);
        try {
            frequency.addValue(null);
            fail("Expected NullPointerException or IllegalArgumentException");
        } catch (NullPointerException | IllegalArgumentException e) {
            // Success
        }
    }

    @Test
    public void testAddValue_CharHandling() {
        // char is not explicitly converted to Long in the 'if (v instanceof Integer)' block,
        // so it stays as Character.
        char val = 'A';
        frequency.addValue(val);
        assertEquals(1L, frequency.getCount(val));
    }
}
